    private static JSONObject done(JSONObject s,String event,JSONObject effect,boolean concentration)throws Exception{if(concentration){JSONObject a=new JSONObject(effect.toString()).put("spell",effect.optString("canonical_spell",canonical(effect.optString("spell")))).put("slot_level",effect.optInt("slot_level",level(effect.optString("spell"))));s.put("run149_active_concentration",a);}return s.put("run149_spell_resolved",true).put("run149_spell_status","resolvida").put("run149_spell_event",event).put("run149_spell_effect",effect).put("run149_spell_auto_rolls",false);}
    private static JSONObject eventDone(JSONObject s,JSONObject e)throws Exception{return s.put("run149_spell_resolved",true).put("run149_spell_status","evento_resolvido").put("run149_spell_event",e.optString("event")).put("run149_spell_effect",e).put("run149_spell_auto_rolls",false);}
