    private static JSONObject cancelled(JSONObject s,String spell,String token)throws Exception{return s.put("run149_spell_resolved",false).put("run149_spell_status","cancelled").put("run149_spell_reason","conjuracao_cancelada_sem_gasto").put("run149_spell_cancelled",true).put("run149_spell_cancelled_name",spell).put("run149_spell_transaction_token",token).put("run149_spell_auto_rolls",false);}
    private static JSONObject replay(JSONObject s,String spell,String token)throws Exception{return s.put("run149_spell_resolved",true).put("run149_spell_status","replay_ignorado").put("run149_spell_event","idempotent_replay").put("run149_spell_replay_ignored",true).put("run149_spell_transaction_token",token).put("run149_spell_replay_spell",spell).put("run149_spell_auto_rolls",false);}
    private static void clearPending(JSONObject s){if(s==null)return;s.remove("run149_pending_spell");s.remove("run149_pending_spell_slot");s.remove("run149_pending_transaction_token");}
    private static String transactionToken(JSONObject p){if(p==null)return "";String t=p.optString("transaction_id","").trim();if(t.isEmpty())t=p.optString("action_token","").trim();if(t.isEmpty())t=p.optString("idempotency_key","").trim();return t;}
    private static boolean cancelled(JSONObject p){if(p==null)return false;if(p.optBoolean("cancel",false)||p.optBoolean("cancelled",false)||p.optBoolean("cancel_cast",false))return true;String st=n(p.optString("status",""));return st.equals("cancelled")||st.equals("canceled")||st.equals("cancelado")||st.equals("cancelada");}
    private static JSONObject meta(JSONObject o,String school,String casting,String range,String duration,String effect,String manual)throws Exception{return o.put("escola",school).put("tempo_conjuracao",casting).put("alcance",range).put("duracao",duration).put("efeito",effect).put("entrada_manual",manual);}
    private static boolean spendSlot(JSONObject s,int level)throws Exception{JSONArray cur=s.optJSONArray("spell_slots_current");if(cur!=null&&level>=1&&level<=cur.length()){int i=level-1,v=cur.optInt(i,0);if(v>0){cur.put(i,v-1);s.put("spell_slots_current",cur).put("run149_spell_slot_spent_level",level);return true;}}JSONObject pact=s.optJSONObject("pact_magic");if(pact!=null&&pact.optInt("current",0)>0&&pact.optInt("slot_level",0)>=level){pact.put("current",pact.optInt("current",0)-1);s.put("pact_magic",pact).put("run149_pact_slot_spent",true).put("run149_spell_slot_spent_level",pact.optInt("slot_level",level));return true;}return false;}
    private static int spellcastingMod(JSONObject s){String a=n(s.optString("warlock_feature_modifier_ability",s.optString("warlock_spellcasting_ability",s.optString("spellcasting_ability","cha"))));int score;if(a.equals("int")||a.contains("intelig"))score=s.optInt("int_score",s.optInt("int",10));else if(a.equals("wis")||a.contains("sabedoria"))score=s.optInt("wis_score",s.optInt("wis",10));else score=s.optInt("cha_score",s.optInt("cha",10));return (int)Math.floor((score-10)/2.0);}
    private static boolean isFail(String s){String q=n(s);return q.equals("falha")||q.equals("fail")||q.equals("failure")||q.equals("failed");}
    private static int level(String s){String q=n(canonical(s));if(q.equals(n("Cheerful Song"))||q.equals(n("Fresh Paint")))return 0;if(q.equals(n("Accursed Wish"))||q.equals(n("Dark Secret"))||q.equals(n("Suffer")))return 2;if(q.equals(n("Blackened Heart"))||q.equals(n("Blasphemy"))||q.equals(n("Crushing Tide"))||q.equals(n("Resonance"))||q.equals(n("Serpent's Bite")))return 3;if(q.equals(n("Dark Empowerment"))||q.equals(n("Forbidden Obelisk")))return 4;if(q.equals(n("Forgotten Pain"))||q.equals(n("Summon Slime")))return 5;return -1;}
    private static String display(String s){String c=canonical(s);for(String[] x:PT)if(x[0].equals(c))return x[1];return s;}
    private static String canonical(String s){String q=n(s);for(String[] x:PT)if(q.equals(n(x[0]))||q.equals(n(x[1])))return x[0];return "";}
    private static String id(String s){return n(s).replace(' ','_');}
    private static String n(String s){String x=Normalizer.normalize(s==null?"":s.toLowerCase(new Locale("pt","BR")),Normalizer.Form.NFD).replaceAll("\\p{M}+","");return x.replaceAll("[^a-z0-9]+"," ").trim();}
